<script setup lang="ts">
import { computed } from 'vue'
import { ArrowLeft, ArrowRight, Copy, Film, Music2, Type, Sticker, Trash2, X, RotateCcw } from 'lucide-vue-next'
import { tr } from '@/i18n'
import AppSelect from '@/components/AppSelect.vue'
import { kindLabel } from './model'
import type { EditClip, EditorMedia, ClipPatch } from './types'
const props = defineProps<{ clip: EditClip | null; media?: EditorMedia; readOnly: boolean; open: boolean; browsing?: EditorMedia | null }>()
const emit = defineEmits<{ change: [patch: ClipPatch]; trim: [trimIn: number, trimOut: number, speed: number]; remove: []; duplicate: []; close: []; move: [delta: number]; source: []; replace: [] }>()
const sourceDuration = computed(() => props.media?.duration || 0)
const trimOut = computed(() => props.clip?.type === 'audio' && props.clip.loop ? sourceDuration.value : props.clip && (props.clip.type === 'video' || props.clip.type === 'audio') ? props.clip.trim_in + props.clip.duration * (props.clip.type === 'video' ? props.clip.speed : 1) : 0)
function number(event: Event) { return Number((event.target as HTMLInputElement).value) }
function trim(field: 'in' | 'out' | 'speed', value: number) {
  const clip = props.clip
  if (!clip || clip.type !== 'video' && clip.type !== 'audio') return
  if (clip.type === 'audio' && clip.loop) { if (field === 'in') emit('change', { trim_in: value }); return }
  emit('trim', field === 'in' ? value : clip.trim_in, field === 'out' ? value : trimOut.value, field === 'speed' ? value : clip.type === 'video' ? clip.speed : 1)
}
</script>
<template>
  <aside class="editor-inspector" :class="{ 'is-open': open }" :aria-label="tr('选中项属性')">
    <header class="editor-panel-heading"><h2>{{ clip ? tr('{p0}属性', { p0: kindLabel(clip.type) }) : tr('片段属性') }}</h2><button class="editor-icon-btn editor-mobile-only" :aria-label="tr('关闭属性')" @click="emit('close')"><X :size="16" /></button></header>
    <template v-if="clip">
      <div class="editor-inspector-item"><component :is="{ video: Film, audio: Music2, subtitle: Type, sticker: Sticker }[clip.type]" :size="19" /><div><strong>{{ clip.type === 'subtitle' ? tr('字幕片段') : clip.name }}</strong><small>{{ clip.duration.toFixed(2) }}s <template v-if="sourceDuration">/ {{ sourceDuration.toFixed(2) }}s</template></small></div><button class="editor-icon-btn" :disabled="readOnly" :aria-label="tr('复制片段')" @click="emit('duplicate')"><Copy :size="14" /></button></div>
      <div class="editor-inspector-scroll"><fieldset :disabled="readOnly">
        <section class="editor-property"><h3>{{ tr('时间') }}</h3><div class="editor-field-pair"><label>{{ tr('开始（秒）') }}<input type="number" min="0" step=".1" :value="clip.start" @input="emit('change', { start: number($event) })" /></label><label>{{ tr('时长（秒）') }}<input type="number" min=".05" step=".1" :value="clip.duration" @input="emit('change', { duration: number($event) })" /></label></div></section>
        <template v-if="clip.type === 'video' || clip.type === 'audio'">
          <section class="editor-property"><h3>{{ tr('裁剪') }}</h3><div class="editor-field-pair"><label>{{ tr('入点') }}<input type="number" min="0" step=".1" :max="sourceDuration" :value="clip.trim_in" @input="trim('in', number($event))" /></label><label>{{ tr('出点') }}<input type="number" min=".05" step=".1" :disabled="clip.type === 'audio' && clip.loop" :max="sourceDuration" :value="trimOut" @input="trim('out', number($event))" /></label></div><label v-if="clip.type === 'video'" class="editor-property-row">{{ tr('速度') }}<AppSelect :model-value="String(clip.speed)" :options="[.25,.5,1,1.5,2,4].map(rate=>({value:String(rate),label:`${rate}×`}))" :ariaLabel="tr('速度')" :disabled="readOnly" density="compact" @update:model-value="trim('speed',Number($event))" /></label></section>
          <section class="editor-property"><h3>{{ tr('声音') }}</h3><label class="editor-slider"><span>{{ clip.type === 'audio' ? tr('BGM 音量') : tr('原视频声音') }}</span><output>{{ Math.round(clip.volume * 100) }}%</output><input type="range" min="0" max="1" step=".01" :value="clip.volume" @input="emit('change', { volume: number($event) })" /></label></section>
        </template>
        <section v-if="clip.type === 'video'" class="editor-property"><h3>{{ tr('画面') }}</h3><label class="editor-slider"><span>{{ tr('缩放') }}</span><output>{{ Math.round(clip.scale * 100) }}%</output><input type="range" min=".1" max="4" step=".01" :value="clip.scale" @input="emit('change', { scale: number($event) })" /></label><div class="editor-field-pair"><button class="editor-btn secondary" :aria-pressed="clip.fit === 'contain'" @click="emit('change', { fit: 'contain' })">{{ tr('适应画布') }}</button><button class="editor-btn secondary" :aria-pressed="clip.fit === 'cover'" @click="emit('change', { fit: 'cover' })">{{ tr('填满画布') }}</button></div><button class="editor-link" @click="emit('change', { scale: 1, fit: 'contain' })"><RotateCcw :size="13" />{{ tr('重置画面') }}</button><button class="editor-link" @click="emit('source')">{{ tr('在分镜中查看') }}<ArrowRight :size="13" /></button><button class="editor-link" @click="emit('replace')">{{ tr('替换为此分镜当前视频') }}<ArrowRight :size="13" /></button></section>
        <section v-if="clip.type === 'audio'" class="editor-property"><h3>{{ tr('淡入淡出') }}</h3><div class="editor-field-pair"><label>{{ tr('淡入（秒）') }}<input type="number" min="0" step=".1" :max="clip.duration" :value="clip.fade_in" @input="emit('change', { fade_in: number($event) })" /></label><label>{{ tr('淡出（秒）') }}<input type="number" min="0" step=".1" :max="clip.duration" :value="clip.fade_out" @input="emit('change', { fade_out: number($event) })" /></label></div><label class="editor-check"><input type="checkbox" :checked="clip.loop" @input="emit('change', { loop: ($event.target as HTMLInputElement).checked })" />{{ tr('循环到片段结束') }}</label></section>
        <template v-if="clip.type === 'subtitle'"><section class="editor-property"><h3>{{ tr('文字内容') }}</h3><textarea :aria-label="tr('字幕内容')" rows="4" maxlength="2000" :value="clip.text" @input="emit('change', { text: ($event.target as HTMLTextAreaElement).value })"></textarea></section><section class="editor-property"><h3>{{ tr('样式') }}</h3><div class="editor-field-pair"><label>{{ tr('字号') }}<input type="number" min="12" max="160" :value="clip.font_size" @input="emit('change', { font_size: number($event) })" /></label><label>{{ tr('颜色') }}<input type="color" :value="clip.color" @input="emit('change', { color: ($event.target as HTMLInputElement).value })" /></label></div><label class="editor-slider"><span>{{ tr('距底部') }}</span><output>{{ clip.bottom }}%</output><input type="range" min="0" max="90" :value="clip.bottom" @input="emit('change', { bottom: number($event) })" /></label></section></template>
        <section v-if="clip.type === 'sticker'" class="editor-property"><h3>{{ tr('位置与大小') }}</h3><div class="editor-field-pair"><label>X %<input type="number" min="0" max="100" :value="clip.x" @input="emit('change', { x: number($event) })" /></label><label>Y %<input type="number" min="0" max="100" :value="clip.y" @input="emit('change', { y: number($event) })" /></label></div><label class="editor-slider"><span>{{ tr('缩放') }}</span><output>{{ Math.round(clip.scale * 100) }}%</output><input type="range" min=".1" max="4" step=".01" :value="clip.scale" @input="emit('change', { scale: number($event) })" /></label><label class="editor-slider"><span>{{ tr('不透明度') }}</span><output>{{ Math.round(clip.opacity * 100) }}%</output><input type="range" min="0" max="1" step=".01" :value="clip.opacity" @input="emit('change', { opacity: number($event) })" /></label></section>
        <section class="editor-property"><h3>{{ tr('移动片段') }}</h3><div class="editor-field-pair"><button class="editor-btn secondary" @click="emit('move', -1)"><ArrowLeft :size="12" />{{ tr('前移 1 秒') }}</button><button class="editor-btn secondary" @click="emit('move', 1)">{{ tr('后移 1 秒') }}<ArrowRight :size="12" /></button></div></section>
      </fieldset></div><footer class="editor-inspector-footer"><button class="editor-link danger" :disabled="readOnly" @click="emit('remove')"><Trash2 :size="14" />{{ tr('从时间线移除') }}</button><small>{{ tr('原始素材保留') }}</small></footer>
    </template><div v-else class="editor-empty"><Film :size="28" /><span>{{ browsing?.name || tr('选择时间线中的片段以编辑属性') }}</span><span v-if="browsing">{{ tr('浏览素材不会修改时间线，请点击加号添加') }}</span></div>
  </aside>
</template>
